use std::collections::HashSet;

/// Removes duplicates from a vector of integers.
///
/// # Parameters
/// - `nums`: A vector of integers.
///
/// # Returns
/// A vector of integers containing only the unique elements from the input vector.
///
/// # Specification
/// - Requires: `nums` is a vector of integers.
/// - Ensures: The returned vector contains only unique integers from `nums`.
/// - Ensures: The length of the returned vector is less than or equal to the length of `nums`.
/// - Ensures: For all elements `x` in the returned vector, `x` is in `nums`.
fn remove_duplicates(nums: Vec<i32>) -> Vec<i32> {
    // Invariant: `seen` contains all elements that have been inserted so far.
    // Invariant: `result` contains all unique elements in the order they were first encountered.
    let mut seen = HashSet::new();
    let mut result = Vec::new();

    // Loop invariant: For each element `num` in `nums`, if `num` is not in `seen`,
    // it will be added to `result` and `seen`.
    for &num in nums.iter() {
        // Precondition: `num` is an integer.
        // Postcondition: If `num` was not in `seen`, it is now added to `result`.
        if seen.insert(num) {
            result.push(num);
        }
    }

    // Ensures: The result contains only unique elements.
    result
}

fn main() {
    let nums = vec![1, 2, 2, 3, 4, 4, 5];
    let unique_nums = remove_duplicates(nums);
    // Ensures: The output is a vector of unique integers.
    println!("{:?}", unique_nums); // Output: [1, 2, 3, 4, 5]
}